define(["core/modal_factory","core/modal_events","core/notification","paygw_mbwaymock/repository"],function(ModalFactory,ModalEvents,Notification,Repository){"use strict";var buildPaymentBody=function(){return['<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,sans-serif;padding:6px 2px 2px;">','<div style="text-align:center;margin-bottom:22px;">','<div style="display:inline-flex;align-items:center;gap:8px;">','<div style="border-top:2px solid #c8102e;border-bottom:2px solid #c8102e;padding:5px 11px;line-height:1;">','<span style="font-size:22px;font-weight:500;color:#222;font-family:\'Helvetica Neue\',Helvetica,Arial,sans-serif;letter-spacing:0;">MB</span>','</div>','<div style="display:flex;flex-direction:column;align-items:flex-start;line-height:1.2;">','<span style="font-size:20px;font-weight:300;color:#222;font-family:\'Helvetica Neue\',Helvetica,Arial,sans-serif;letter-spacing:.5px;">way</span>','<span style="font-size:9px;color:#bbb;letter-spacing:.5px;font-weight:300;">simula&ccedil;&atilde;o</span>','</div></div></div>','<div style="border-left:3px solid #98cd6b;background:#f0fdf4;padding:7px 11px;margin-bottom:18px;border-radius:0 4px 4px 0;font-size:12px;color:#155724;">','Ambiente de simula&ccedil;&atilde;o &mdash; nenhum valor real ser&aacute; debitado.','</div>','<div id="mbway-form-area">','<label style="display:block;font-size:11px;font-weight:600;color:#9ca3af;letter-spacing:.6px;text-transform:uppercase;margin-bottom:6px;">N&uacute;mero de Telem&oacute;vel</label>','<div style="display:flex;border:1px solid #e5e7eb;border-radius:7px;overflow:hidden;background:#fff;">','<span style="background:#f9fafb;padding:10px 12px;font-size:13px;color:#6b7280;border-right:1px solid #f3f4f6;white-space:nowrap;">&#127477;&#127481; +351</span>','<input type="tel" id="mbway-phone-input" maxlength="9" placeholder="912 345 678" style="flex:1;border:none;outline:none;padding:10px 12px;font-size:16px;color:#111827;background:transparent;width:100%;">','</div>','<p style="font-size:11px;color:#d1d5db;margin:4px 0 18px 2px;">9 d&iacute;gitos sem espa&ccedil;os &middot; ex: 912345678</p>','<button id="mbway-confirm-btn" type="button" style="width:100%;background:#98cd6b;color:#fff;border:none;border-radius:7px;padding:11px;font-size:14px;font-weight:600;cursor:pointer;letter-spacing:.2px;">Confirmar Pagamento</button>','</div>','<div id="mbway-loading-area" style="display:none;text-align:center;padding:18px 0;">','<style>@keyframes mbspin{to{transform:rotate(360deg)}}</style>','<div style="width:34px;height:34px;margin:0 auto 12px;border:2px solid #e5e7eb;border-top-color:#98cd6b;border-radius:50%;animation:mbspin .75s linear infinite;"></div>','<p style="font-size:14px;font-weight:500;color:#374151;margin:0 0 3px;">A processar pagamento...</p>','<p style="font-size:12px;color:#9ca3af;margin:0;">Por favor aguarde</p>','</div>','</div>'].join('');};var buildBillingBody=function(){return['<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,sans-serif;padding:6px 2px 2px;">','<p style="font-size:14px;color:#374151;margin-bottom:6px;">A fatura deve ser emitida em nome de quem?</p>','<p style="font-size:11px;color:#9ca3af;margin:0 0 18px;">Os dados s&atilde;o retirados automaticamente do seu perfil.</p>','<div style="display:flex;gap:12px;margin-bottom:16px;">','<button id="mbway-bill-personal" type="button" style="flex:1;border:2px solid #98cd6b;border-radius:10px;padding:18px 12px;background:#f0fdf4;cursor:pointer;text-align:center;">','<div style="font-size:24px;margin-bottom:6px;">&#128100;</div>','<div style="font-size:14px;font-weight:600;color:#98cd6b;">Pessoal</div>','<div style="font-size:11px;color:#6b7280;margin-top:3px;">NIF pessoal</div>','</button>','<button id="mbway-bill-company" type="button" style="flex:1;border:2px solid #e5e7eb;border-radius:10px;padding:18px 12px;background:#fff;cursor:pointer;text-align:center;">','<div style="font-size:24px;margin-bottom:6px;">&#127970;</div>','<div style="font-size:14px;font-weight:600;color:#374151;">Empresa</div>','<div style="font-size:11px;color:#6b7280;margin-top:3px;">NIF da empresa</div>','</button>','</div>','<div id="mbway-billing-loading" style="display:none;text-align:center;padding:8px 0 4px;">','<div style="width:28px;height:28px;margin:0 auto 8px;border:2px solid #e5e7eb;border-top-color:#98cd6b;border-radius:50%;animation:mbspin .75s linear infinite;"></div>','<p style="font-size:13px;color:#374151;margin:0;">A enviar comprovativo...</p>','</div>','</div>'].join('');};var pollStatus=function(txn_ref,modal,attempts,resolve,reject){if(attempts<=0){var l=document.getElementById('mbway-loading-area');var f=document.getElementById('mbway-form-area');if(l){l.style.display='none';}if(f){f.style.display='block';}Notification.alert('Tempo esgotado','O pagamento excedeu o tempo limite. Por favor tente novamente.','OK');reject(new Error('timeout'));return;}setTimeout(function(){Repository.checkPayment(txn_ref).then(function(result){if(result.status==='success'){showBillingModal(txn_ref,modal,resolve,reject);}else if(result.status==='failed'){var l2=document.getElementById('mbway-loading-area');var f2=document.getElementById('mbway-form-area');if(l2){l2.style.display='none';}if(f2){f2.style.display='block';}Notification.alert('Pagamento recusado','O pagamento foi recusado. Por favor tente novamente.','OK');reject(new Error('failed'));}else{pollStatus(txn_ref,modal,attempts-1,resolve,reject);}}).catch(function(){pollStatus(txn_ref,modal,attempts-1,resolve,reject);});},2000);};var sendAndClose=function(txn_ref,billingType,billingModal,resolve){var loading=document.getElementById('mbway-billing-loading');var btnP=document.getElementById('mbway-bill-personal');var btnC=document.getElementById('mbway-bill-company');if(loading){loading.style.display='block';}if(btnP){btnP.disabled=true;btnP.style.opacity='0.6';}if(btnC){btnC.disabled=true;btnC.style.opacity='0.6';}Repository.sendComprovativo(txn_ref,billingType).then(function(){billingModal.hide();resolve();}).catch(function(){billingModal.hide();resolve();});};var showBillingModal=function(txn_ref,paymentModal,resolve,reject){ModalFactory.create({title:'Dados para Faturação',body:buildBillingBody()}).then(function(billingModal){paymentModal.getRoot().off(ModalEvents.hidden);paymentModal.hide();var bRoot=billingModal.getRoot();var clicked=false;bRoot.on('click','#mbway-bill-personal,#mbway-bill-company',function(){if(clicked){return;}clicked=true;var billingType=this.id==='mbway-bill-personal'?'personal':'company';sendAndClose(txn_ref,billingType,billingModal,resolve);});billingModal.show();bRoot.on(ModalEvents.hidden,function(){if(!clicked){resolve();}});}).catch(function(){paymentModal.hide();resolve();});};return{process:function(component,paymentArea,itemId,description){return new Promise(function(resolve,reject){ModalFactory.create({title:'Pagamento MB WAY',body:buildPaymentBody()}).then(function(modal){modal.show();var root=modal.getRoot();var paymentStarted=false;setTimeout(function(){var inp=document.getElementById('mbway-phone-input');if(inp){inp.focus();}},300);root.on('click','#mbway-confirm-btn',function(){var inp=document.getElementById('mbway-phone-input');var phone=inp?inp.value.replace(/[\s\-]/g,''):'';if(!/^9[1236]\d{7}$/.test(phone)){Notification.alert('Número inválido','Introduza um número português válido com 9 dígitos (ex: 912345678).','OK');return;}paymentStarted=true;var f=document.getElementById('mbway-form-area');var l=document.getElementById('mbway-loading-area');if(f){f.style.display='none';}if(l){l.style.display='block';}Repository.createPayment(component,paymentArea,itemId,description).then(function(result){if(result&&result.success){pollStatus(result.txn_ref,modal,30,resolve,reject);}else{paymentStarted=false;if(f){f.style.display='block';}if(l){l.style.display='none';}Notification.alert('Erro','Não foi possível iniciar o pagamento.','OK');reject(new Error('create failed'));}}).catch(function(e){paymentStarted=false;if(f){f.style.display='block';}if(l){l.style.display='none';}Notification.exception(e);reject(e);});});root.on(ModalEvents.hidden,function(){if(!paymentStarted){window.location.reload();}});}).catch(function(e){Notification.exception(e);reject(e);});});}};});
